<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/offline-fixtures.php';
use App\Services\{Products,Customers,ProductStock,RepresentativeStock,Promotions,Invoices,Inventory,Reports,InvoiceDocuments};use App\Support\{Database,LocalPdf};
if(PHP_SAPI!=='cli'||getenv('DB_NAME')!=='dharma_sales_phase9_test')throw new RuntimeException('Isolated test database required.');
$pdo=Database::connect();$f=offlineFixtures($pdo);$admin=$f['actors']['admin'];$rep=$f['actors']['rep'];$count=0;
$check=static function($ok,$label)use(&$count){if(!$ok)throw new RuntimeException($label);$count++;};
$category=(string)$pdo->query('SELECT category_id FROM products WHERE id='.(int)$f['products'][0])->fetchColumn();
$productInput=['create_token'=>Inventory::uuid(),'name'=>'Phase12 '.str_repeat('Long Ayurveda product ',7),'category_id'=>$category,'unit_of_measure'=>'unit','selling_price'=>'125.50','cost_price'=>'','description'=>'Isolated usability workflow'];
$product=(new Products($pdo))->save($admin,$productInput);$check(preg_match('/^P[0-9]{3,}$/D',$product['sku'])===1,'Automatic product code');
$location=$pdo->query('SELECT id town_id,district_id FROM location_towns ORDER BY id LIMIT 1')->fetch();
$customerInput=['create_token'=>Inventory::uuid(),'shop_name'=>'Phase12 '.str_repeat('Long shop ',12),'contact_person'=>'Isolated customer','phone'=>'+999'.random_int(100000000,999999999),'alternate_phone'=>'','address'=>str_repeat('Test address ',20),'district_id'=>(string)$location['district_id'],'town_id'=>(string)$location['town_id'],'customer_type'=>'PHARMACY','credit_terms_days'=>'30','credit_limit'=>'1000.00','notes'=>'Disposable workflow only'];
$customer=(new Customers($pdo))->save($admin,$customerInput);$check(preg_match('/^C[0-9]{3,}$/D',$customer['customer_code'])===1,'Automatic customer code');
foreach([['service'=>new Products($pdo),'input'=>$productInput],['service'=>new Customers($pdo),'input'=>$customerInput]] as $retry){try{$retry['service']->save($admin,$retry['input']);throw new RuntimeException('Duplicate master accepted');}catch(\App\Support\ProductException|\App\Support\CustomerException $e){$check($e->status===422,'Repeated create token cannot duplicate record');}}
$stock=new ProductStock($pdo);$stockInput=['request_id'=>Inventory::uuid(),'product_id'=>(string)$product['id'],'quantity'=>'200','selling_price'=>'125.50','product_version'=>(string)$product['version']];$stock->post($admin,$stockInput);$check($stock->post($admin,$stockInput)['replayed'],'Stock receipt idempotency preserved');
$transfer=new RepresentativeStock($pdo);$allocation=['request_id'=>Inventory::uuid(),'rep_id'=>(string)$rep['id'],'product_id'=>(string)$product['id'],'quantity'=>'50'];$transfer->post($admin,$allocation,'ALLOCATE');$check($transfer->post($admin,$allocation,'ALLOCATE')['replayed'],'Allocation idempotency preserved');
(new Promotions($pdo))->save($admin,['request_id'=>Inventory::uuid(),'name'=>'Phase12 Buy2Get1','description'=>'Isolated test','product_id'=>(string)$product['id'],'type'=>'BUY_X_GET_Y','buy_quantity'=>'2','free_quantity'=>'1','percent_rate'=>'','fixed_discount'=>'','start_date'=>'','end_date'=>'','is_active'=>'1']);
$invoices=new Invoices($pdo);$invoices->customerSettings($admin,['customer_id'=>(string)$customer['id'],'version'=>(string)$customer['version'],'assigned_rep_id'=>(string)$rep['id'],'allow_credit_sales'=>'1']);
$issue=static function($type,$cash)use($invoices,$rep,$product,$customer){$in=['request_id'=>Inventory::uuid(),'customer_id'=>(string)$customer['id'],'payment_type'=>$type,'amount_received'=>$cash,'items'=>[['product_id'=>(string)$product['id'],'quantity'=>'2']]];$in['review_hash']=$invoices->review($rep,$in)['review_hash'];return $invoices->issue($rep,$in)['invoice_id'];};
$invoice=$issue('CASH','300.00');$credit=$issue('CREDIT','0.00');$record=$invoices->get($rep,$invoice);$check($record['grand_total']==='251.00'&&$record['items'][0]['free_quantity']==1&&$record['receipts'][0]['change_amount']==='49.00','Cash, change, free stock exact');
$invoices->pay($rep,$credit,['request_id'=>Inventory::uuid(),'amount_received'=>'50.00']);$check($invoices->get($rep,$credit)['outstanding']==='201.00','Credit partial payment');
$invoices->void($admin,$invoice,['request_id'=>Inventory::uuid(),'reason'=>'Isolated Phase12 reversal']);$check($invoices->get($admin,$invoice)['refund_due']==='251.00','Void refund liability');
$qty=$pdo->query('SELECT quantity FROM representative_stock_balances WHERE rep_id='.(int)$rep['id'].' AND product_id='.(int)$product['id'])->fetchColumn();$check((string)$qty==='47','Paid/free reversal restores exactly once');
$check($stock->reconciliation($admin)===[]&&$transfer->reconciliation($admin)===[],'Warehouse and representative reconcile');
foreach((new Reports($pdo))->reconciliation($admin) as $label=>$violations)$check($violations===0,$label);
$pdf=LocalPdf::generate(InvoiceDocuments::render((new InvoiceDocuments($pdo))->snapshot($admin,$invoice),'a4','/admin/invoices',true));$check(str_starts_with($pdf,'%PDF-'),'Workflow PDF valid');
// Competing requests with the same server-issued form token are constrained by
// existing unique codes/history, without changing financial idempotency semantics.
$workerPipes=[];$workers=[];$raceInput=$productInput;$raceInput['create_token']=Inventory::uuid();
for($i=0;$i<2;$i++){$pipes=[];$worker=proc_open([PHP_BINARY,APP_ROOT.'/tests/phase12-code-worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,APP_ROOT,null,['bypass_shell'=>true]);fwrite($pipes[0],json_encode(['actor'=>$admin,'input'=>$raceInput]));fclose($pipes[0]);$workers[]=[$worker,$pipes];}
$answers=[];foreach($workers as [$worker,$pipes]){$answers[]=trim(stream_get_contents($pipes[1]));$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$check(proc_close($worker)===0,'Create race worker '.$error);}sort($answers);$check($answers===['CREATED','REJECTED'],'Concurrent same-token creation produces one record');
$raceCustomer=$customerInput;$raceCustomer['create_token']=Inventory::uuid();$raceCustomer['phone']='+999'.random_int(100000000,999999999);$workers=[];
for($i=0;$i<2;$i++){$pipes=[];$worker=proc_open([PHP_BINARY,APP_ROOT.'/tests/phase12-code-worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,APP_ROOT,null,['bypass_shell'=>true]);fwrite($pipes[0],json_encode(['kind'=>'C','actor'=>$admin,'input'=>$raceCustomer]));fclose($pipes[0]);$workers[]=[$worker,$pipes];}
$answers=[];foreach($workers as [$worker,$pipes]){$answers[]=trim(stream_get_contents($pipes[1]));$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$check(proc_close($worker)===0,'Customer race worker '.$error);}sort($answers);$check($answers===['CREATED','REJECTED'],'Concurrent customer token produces one record');
foreach([[new Products($pdo),$productInput],[new Customers($pdo),$customerInput]] as [$service,$bad]){unset($bad['create_token']);try{$service->save($admin,$bad);throw new RuntimeException('Unsafe automatic create without token');}catch(\App\Support\ProductException|\App\Support\CustomerException $e){$check($e->status===422,'Missing automatic submission token rejected');}}
echo "$count Phase12 automatic-code, duplicate-submission and complete business workflow checks passed in isolated database.\n";
